// Build a ±1h availability window around the AI-parsed preferred datetime.
// Also pre-computes the 1-hour event end time for the Create Event node.
// If the AI could not parse a date/time, flag needs_time (handled downstream).
const out = $('AI Agent \u2014 Understand Booking Intent').first().json.output || {};
const preferred = (out.preferred_datetime || '').trim();
const base = {
  preferred,
  event_end: '',
  customer_name: (out.customer_name || '').trim(),
  notes: (out.notes || '').trim(),
  window_start: '',
  window_end: '',
  needs_time: false,
};
if (!preferred || isNaN(new Date(preferred).getTime())) {
  base.needs_time = true;
  return [{ json: base }];
}
const t = new Date(preferred).getTime();
base.window_start = new Date(t - 3600000).toISOString();
base.window_end = new Date(t + 3600000).toISOString();
base.event_end = new Date(t + 3600000).toISOString();
return [{ json: base }];

// Decide whether the requested 1-hour slot is free. If not, propose the next 3
// free 1-hour slots around the preferred time (same day, ±hours). If the AI could
// not parse a date/time, flag needs_time so WhatsApp asks the customer for one.
// Also builds the exact reply texts used by the WhatsApp nodes below.
const win = $input.first().json;
const busy = $('Calendar \u2014 Check Availability').all().map(i => i.json);
function toMs(v) { const t = new Date(v).getTime(); return isNaN(t) ? null : t; }
function overlaps(s, e) {
  return busy.some(b => {
    const bs = toMs(b.start && (b.start.dateTime || b.start.date));
    const be = toMs(b.end && (b.end.dateTime || b.end.date));
    return bs !== null && be !== null && s < be && e > bs;
  });
}
const biz = $('CONFIG \u2014 Business').first().json.business_name;
let slot_free = false, alternatives = [], confirm_text = '', reply_text = '';
if (win.needs_time) {
  reply_text = 'Thanks for reaching out to ' + biz + '! 😊 To book your appointment, please reply with your preferred date and time (e.g. "tomorrow 4pm").';
} else {
  const pref = toMs(win.preferred);
  slot_free = pref !== null && !overlaps(pref, pref + 3600000);
  if (slot_free) {
    confirm_text = '\u2705 Appointment confirmed at ' + biz + '!\n\n📅 ' + win.preferred
      + (win.customer_name ? '\n👤 ' + win.customer_name : '')
      + '\n\nReply CANCEL to cancel or RESCHEDULE to move it. See you soon! 🙏';
  } else {
    for (const h of [-2, -1, 1, 2, 3, 4, -3, 5]) {
      const s = pref + h * 3600000;
      if (!overlaps(s, s + 3600000)) {
        alternatives.push(new Date(s).toISOString());
        if (alternatives.length >= 3) break;
      }
    }
    reply_text = 'Sorry, ' + win.preferred + ' is already booked. 😕\n\nHere are 3 alternatives:\n'
      + alternatives.map(a => '\u2022 ' + a).join('\n')
      + '\n\nReply with the one you prefer, or suggest another time.';
  }
}
return [{ json: Object.assign({}, win, { slot_free, alternatives, confirm_text, reply_text }) }];

// Find the customer's upcoming event: first try the sender's phone number in the
// event description (written there by Calendar — Create Event), then fall back to
// the customer name in the event summary.
const from = $('New WhatsApp Message').first().json.entry[0].changes[0].value.messages[0].from;
const name = (($('AI Agent \u2014 Understand Booking Intent').first().json.output || {}).customer_name || '').toLowerCase();
const events = $('Calendar \u2014 Find Upcoming Events').all().map(i => i.json);
const hit = events.find(e => (e.description || '').includes(from))
  || (name ? events.find(e => (e.summary || '').toLowerCase().includes(name)) : null);
return [{ json: {
  event_id: hit ? hit.id : '',
  event_summary: hit ? (hit.summary || '') : '',
  event_start: hit && hit.start ? (hit.start.dateTime || hit.start.date || '') : '',
  found: !!hit,
} }];

// Build one Telegram digest line for this booking-flow run.
function ran(name) { try { return $(name).all().length > 0; } catch (e) { return false; } }
const biz = $('CONFIG \u2014 Business').first().json.business_name;
const trigger = $('New WhatsApp Message').first().json.entry[0].changes[0].value.messages[0];
const intent = (($('AI Agent \u2014 Understand Booking Intent').first().json.output) || {}).intent || 'unknown';
const status = ran('Update Sheet \u2014 BOOKED') ? 'BOOKED \u2705'
  : ran('Update Sheet \u2014 PENDING_SLOT') ? 'PENDING_SLOT \u23f3 (alternatives suggested)'
  : ran('Update Sheet \u2014 CANCELLED') ? 'CANCELLED \u274c'
  : ran('Update Sheet \u2014 RESCHEDULE_REQUESTED') ? 'RESCHEDULE_REQUESTED 🔁'
  : 'HANDLED 💬';
const lines = [
  '📅 *Booking Activity \u2014 ' + biz + '*', '',
  '👤 ' + trigger.from,
  '💬 "' + String(trigger.text.body).slice(0, 140) + '"',
  '🧭 Intent: ' + intent,
  '📌 Status: ' + status,
];
return [{ json: { digest: lines.join('\n') } }];

// Keep customers whose Last Visit is older than recall_days and who have a phone number.
// Phone_raw keeps the original sheet value for the Sheets update matcher; Phone is
// the digit-only version used for sending the WhatsApp message.
const days = parseInt($('CONFIG \u2014 Recall').first().json.recall_days || '60', 10);
const cutoff = Date.now() - days * 24 * 3600 * 1000;
const rows = $('Read Customers').all().map(i => i.json);
const inactive = rows.filter(r => {
  const rawPhone = r.Phone || r.phone || '';
  const lv = new Date(r['Last Visit'] || r.last_visit || '').getTime();
  return String(rawPhone).trim() !== '' && !isNaN(lv) && lv < cutoff;
});
return inactive.map(r => ({ json: {
  Name: r.Name || r.name || '',
  Phone: String(r.Phone || r.phone || '').replace(/\D/g, ''),
  Phone_raw: r.Phone || r.phone || '',
  'Last Visit': r['Last Visit'] || r.last_visit || '',
} }));

// Count the recall run for the Telegram digest.
const sent = $('WhatsApp \u2014 Send Re-engagement').all().length;
const names = $('Code \u2014 Filter Inactive 60+ Days').all().map(i => i.json.Name).filter(Boolean).slice(0, 10);
const lines = [
  '📣 *Weekly Recall Digest \u2014 ' + new Date().toISOString().slice(0, 10) + '*', '',
  '💬 ' + sent + ' re-engagement WhatsApp messages sent',
];
if (names.length) { lines.push('', '👥 ' + names.join(', ')); }
lines.push('', 'Sheet status \u2192 RECALLED. Watch for replies in Flow A!');
return [{ json: { digest: lines.join('\n') } }];
